{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, _ in pts), max(r for r, _ in pts)
    c0, c1 = min(c for _, c in pts), max(c for _, c in pts)
    frame = grid[r0][c0]
    inner_colors = {grid[r][c] for r, c in pts if grid[r][c] != frame}
    if len(inner_colors) != 1:
        return [row[:] for row in grid]
    color = next(iter(inner_colors))
    core = [(r, c) for r, c in pts if grid[r][c] == color]
    cr0, cr1 = min(r for r, _ in core), max(r for r, _ in core)
    cc0, cc1 = min(c for _, c in core), max(c for _, c in core)
    grow_r, grow_c = cr1-cr0+1, cc1-cc0+1
    out = [row[:] for row in grid]
    for r in range(max(0, r0-grow_r), min(h-1, r1+grow_r)+1):
        for c in range(max(0, c0-grow_c), min(w-1, c1+grow_c)+1):
            if out[r][c] == 0:
                out[r][c] = color
    return out
